mapper.select:
SELECT t.*, u.name, u.username
FROM dm_doc_user t
LEFT JOIN base_user u ON t.user_id = u.id
WHERE t.deleted = false
AND u.deleted = false

    AND t.doc_id = #{query.docId}


    AND t.user_id = #{query.userId}


    AND u.name LIKE concat('%', #{query.name}, '%')


    AND u.username LIKE concat('%', #{query.username}, '%')


    ORDER BY ${sorter}

SELECT t.* FROM base_user t WHERE t.deleted = false AND t.id IN (
    SELECT a.user_id FROM dm_doc_user a WHERE a.deleted = false AND a.doc_id = #{docId}
)
